#!/usr/bin/env bash
# ZONO — ZI centered/enlarged on home + Daily Center full-width. Push.
set -euo pipefail
git am --abort 2>/dev/null || true
git fetch origin main && git checkout main && git merge --ff-only origin/main 2>/dev/null || echo "(applying onto current HEAD)"
echo "" | base64 -d > /tmp/ui-tweaks.patch
git am -3 /tmp/ui-tweaks.patch
git push origin main
echo "✅ UI tweaks applied and pushed."
